using UnityEngine;
using UnityEngine.InputSystem;

namespace FarmPrototype.Player
{
    public sealed class FarmEquipmentController : MonoBehaviour
    {
        [SerializeField] private GameObject hoe;
        [SerializeField] private GameObject seeds;
        [SerializeField] private GameObject wateringCan;

        private void Start()
        {
            var socket = Find(transform, "Prop_R_Socket");
            if (socket == null) return;
            Attach(hoe, socket, new Vector3(0.02f, 0f, 0f), new Vector3(10f, 90f, 80f));
            Attach(seeds, socket, new Vector3(0f, 0f, 0f), new Vector3(0f, 90f, 0f));
            Attach(wateringCan, socket, new Vector3(0.03f, 0f, 0f), new Vector3(0f, 90f, 70f));
            Select(hoe);
        }

        private void Update()
        {
            var keyboard = Keyboard.current;
            if (keyboard == null) return;
            if (keyboard.digit1Key.wasPressedThisFrame) Select(hoe);
            if (keyboard.digit2Key.wasPressedThisFrame) Select(seeds);
            if (keyboard.digit3Key.wasPressedThisFrame) Select(wateringCan);
            if (keyboard.digit4Key.wasPressedThisFrame) Select(null);
        }

        private void Select(GameObject selected)
        {
            if (hoe != null) hoe.SetActive(hoe == selected);
            if (seeds != null) seeds.SetActive(seeds == selected);
            if (wateringCan != null) wateringCan.SetActive(wateringCan == selected);
        }

        private static void Attach(GameObject item, Transform socket, Vector3 position, Vector3 rotation)
        {
            if (item == null) return;
            item.transform.SetParent(socket, false);
            item.transform.localPosition = position;
            item.transform.localRotation = Quaternion.Euler(rotation);
        }

        private static Transform Find(Transform root, string targetName)
        {
            foreach (var child in root.GetComponentsInChildren<Transform>(true))
                if (child.name == targetName) return child;
            return null;
        }
    }
}
